INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('42e63abf-02e4-5909-9d7d-d0f55f80fe2d', 'Brazil BM&FBOVESPA Novo Mercado Governança Corporativa', 'BM&FBOVESPA Novo Mercado Governança Corporativa 2000', 'This brochure is dedicated to the Novo Mercado, and describes the corporate governance commitments that companies registered in this segment assume in addition to those existing in current legislation. Such commitments refer to the provision of information that facilitate the monitoring and inspection of the acts of the company''s management and controllers; and the adoption of corporate rules that better balance the rights of all shareholders, regardless of their status as controller or investor.', 'This brochure is dedicated to the Novo Mercado, and describes the corporate governance commitments that companies registered in this segment assume in addition to those existing in current legislation. Such commitments refer to the provision of information that facilitate the monitoring and inspection of the acts of the company''s management and controllers; and the adoption of corporate rules that better balance the rights of all shareholders, regardless of their status as controller or investor.', 'This brochure is dedicated to the Novo Mercado, and describes the corporate governance commitments that companies registered in this segment assume in addition to those existing in current legislation. Such commitments refer to the provision of information that facilitate the monitoring and inspection of the acts of the company''s management and controllers; and the adoption of corporate rules that better balance the rights of all shareholders, regardless of their status as controller or investor.', 'Brazil', 'governance', 'in_force', '2000-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_13', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d8b530a1-56cc-53b8-962c-4843b6110d09', 'Brazil Law ,966 of April 28', 'Law No. 9,966 of April 28, 2000', 'Provides for the prevention, control and inspection of pollution caused by the release of oil and other harmful or dangerous substances into waters under national jurisdiction and other provisions.', 'Provides for the prevention, control and inspection of pollution caused by the release of oil and other harmful or dangerous substances into waters under national jurisdiction and other provisions.', 'Provides for the prevention, control and inspection of pollution caused by the release of oil and other harmful or dangerous substances into waters under national jurisdiction and other provisions.', 'Brazil', 'climate', 'in_force', '2000-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_49', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg6', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1da3b6dd-0211-5294-8e7a-e75dbcfcfedb', 'Bulgaria Act amending the Accountancy Act', 'Act amending the Accountancy Act', 'Act amending the Accountancy Act', 'Act amending the Accountancy Act', 'Act amending the Accountancy Act', 'Bulgaria', 'governance', 'in_force', '2025-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_16', ARRAY['mandatory', 'bulgaria', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c5e532ec-f255-5a3c-b3fe-89ccf44c31d7', 'Bulgaria Accountancy Act', 'The Accountancy Act', 'The Accountancy Act of Bulgaria regulates accounting standards, financial reporting, and auditing obligations for businesses, including documentation requirements and sustainability reporting. It applies to various entities like traders, non-trading legal entities, budgetary enterprises, and foreign companies operating within Bulgaria.', 'The Accountancy Act of Bulgaria regulates accounting standards, financial reporting, and auditing obligations for businesses, including documentation requirements and sustainability reporting. It applies to various entities like traders, non-trading legal entities, budgetary enterprises, and foreign companies operating within Bulgaria.', 'The Accountancy Act of Bulgaria regulates accounting standards, financial reporting, and auditing obligations for businesses, including documentation requirements and sustainability reporting. It applies to various entities like traders, non-trading legal entities, budgetary enterprises, and foreign companies operating within Bulgaria.', 'Bulgaria', 'climate', 'in_force', '2024-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_14', ARRAY['sdg13', 'bulgaria', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9e84a04c-84eb-596c-bd7d-aa87caf0be05', 'Bulgaria Independent Financial Audit and Assurance of Sustainability Reporting', 'Independent Financial Audit and Assurance of Sustainability Reporting Act', 'The Independent Financial Audit and Assurance of Sustainability Reporting Act in Bulgaria outlines standards for financial audit and sustainability assurance, aiming to enhance confidence in financial and sustainability reports. It governs auditor qualifications, professional standards, and oversight, targeting statutory auditors and public-interest entities.', 'The Independent Financial Audit and Assurance of Sustainability Reporting Act in Bulgaria outlines standards for financial audit and sustainability assurance, aiming to enhance confidence in financial and sustainability reports. It governs auditor qualifications, professional standards, and oversight, targeting statutory auditors and public-interest entities.', 'The Independent Financial Audit and Assurance of Sustainability Reporting Act in Bulgaria outlines standards for financial audit and sustainability assurance, aiming to enhance confidence in financial and sustainability reports. It governs auditor qualifications, professional standards, and oversight, targeting statutory auditors and public-interest entities.', 'Bulgaria', 'climate', 'in_force', '2024-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_15', ARRAY['sdg13', 'bulgaria', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
