INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0b0f6121-0bdf-5945-aac6-59b7f2aa4454', 'Bulgaria National Code of Corporate Governance', 'National Code of Corporate Governance 2021', 'The rules and norms of this Code are standards for the management and supervision of public companies, which have proven their effectiveness over the years. At the heart of the Code is the understanding of corporate governance as a balanced interaction between shareholders, company management and stakeholders.', 'The rules and norms of this Code are standards for the management and supervision of public companies, which have proven their effectiveness over the years. At the heart of the Code is the understanding of corporate governance as a balanced interaction between shareholders, company management and stakeholders.', 'The rules and norms of this Code are standards for the management and supervision of public companies, which have proven their effectiveness over the years. At the heart of the Code is the understanding of corporate governance as a balanced interaction between shareholders, company management and stakeholders.', 'Bulgaria', 'climate', 'in_force', '2021-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_11', ARRAY['bulgaria', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a955697b-033a-5162-a400-d54f2c08657a', 'Bulgaria’s National Strategy for Low-Carbon Development', 'Bulgaria’s National Strategy for Low-Carbon Development (2021-2030)', 'The Integrated Energy and Climate Plan (INECP) of Bulgaria aims to align the country’s energy policies with the European Union''s climate and energy goals for 2030. The plan outlines the national strategy for reducing greenhouse gas emissions (GHG), increasing energy efficiency, and expanding renewable energy. Bulgaria commits to reducing GHG emissions, primarily from the energy sector, which is the largest contributor to emissions, and boosting renewable energy capacity, particularly in wind, solar, and biomass. Energy efficiency initiatives, including the renovation of buildings and promoting low-emission transport, are also key components of the plan. The document lays out specific goals for 2030, including reducing primary and final energy consumption and enhancing energy security by diversifying natural gas sources and integrating energy markets with neighboring countries. The INECP also includes measures to protect vulnerable consumers and incentivize research and innovation in clean energy technologies.', 'The Integrated Energy and Climate Plan (INECP) of Bulgaria aims to align the country’s energy policies with the European Union''s climate and energy goals for 2030. The plan outlines the national strategy for reducing greenhouse gas emissions (GHG), increasing energy efficiency, and expanding renewable energy. Bulgaria commits to reducing GHG emissions, primarily from the energy sector, which is the largest contributor to emissions, and boosting renewable energy capacity, particularly in wind, solar, and biomass. Energy efficiency initiatives, including the renovation of buildings and promoting low-emission transport, are also key components of the plan. The document lays out specific goals for 2030, including reducing primary and final energy consumption and enhancing energy security by diversifying natural gas sources and integrating energy markets with neighboring countries. The INECP also includes measures to protect vulnerable consumers and incentivize research and innovation in clean energy technologies.', 'The Integrated Energy and Climate Plan (INECP) of Bulgaria aims to align the country’s energy policies with the European Union''s climate and energy goals for 2030. The plan outlines the national strategy for reducing greenhouse gas emissions (GHG), increasing energy efficiency, and expanding renewable energy. Bulgaria commits to reducing GHG emissions, primarily from the energy sector, which is the largest contributor to emissions, and boosting renewable energy capacity, particularly in wind, solar, and biomass. Energy efficiency initiatives, including the renovation of buildings and promoting low-emission transport, are also key components of the plan. The document lays out specific goals for 2030, including reducing primary and final energy consumption and enhancing energy security by diversifying natural gas sources and integrating energy markets with neighboring countries. The INECP also includes measures to protect vulnerable consumers and incentivize research and innovation in clean energy technologies.', 'Bulgaria', 'climate', 'in_force', '2021-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_2', ARRAY['sdg13', 'sdg14', 'sdg10', 'bulgaria', 'sdg7', 'sdg11', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59cbe48d-242e-56ad-96af-5cb8ffe2384c', 'Bulgaria Best Practices with Regards to Information Disclosure', 'Best Practices with Regards to Information Disclosure', 'Bulgarian public companies are obliged to disclose almost all aspects of their activities and management. It is of vital importance for the investors  to receive  the information, disclosed  by  public companies in the certain time limits, set by the legal framework. Often  this is interpreted as an indication  of  a flaw in management or  attempt  to hide poor  financial results. Publishing  delayed  regulated  information can affect  both  the  stock price increasing  its  volatility and  overall  rating. A  best  practice  for  the company  is  to  maintain  a corporate  calendar with specified  dates for information disclosure.', 'Bulgarian public companies are obliged to disclose almost all aspects of their activities and management. It is of vital importance for the investors  to receive  the information, disclosed  by  public companies in the certain time limits, set by the legal framework. Often  this is interpreted as an indication  of  a flaw in management or  attempt  to hide poor  financial results. Publishing  delayed  regulated  information can affect  both  the  stock price increasing  its  volatility and  overall  rating. A  best  practice  for  the company  is  to  maintain  a corporate  calendar with specified  dates for information disclosure.', 'Bulgarian public companies are obliged to disclose almost all aspects of their activities and management. It is of vital importance for the investors  to receive  the information, disclosed  by  public companies in the certain time limits, set by the legal framework. Often  this is interpreted as an indication  of  a flaw in management or  attempt  to hide poor  financial results. Publishing  delayed  regulated  information can affect  both  the  stock price increasing  its  volatility and  overall  rating. A  best  practice  for  the company  is  to  maintain  a corporate  calendar with specified  dates for information disclosure.', 'Bulgaria', 'climate', 'in_force', '2018-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_12', ARRAY['regulations', 'voluntary', 'bulgaria', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1285be7f-adf9-5b40-9dbb-ef52ff2c18b3', 'Bulgaria National Corporate Governance Code', 'National Corporate Governance Code 2016', 'This is the 2016 version of the Bulgarian National Corporate Governance Code. The 2016 Code is a standard for best practice and a support for communication among businesses from different countries. It guides Bulgarian companies on how to apply established best practices and principles of corporate governance.', 'This is the 2016 version of the Bulgarian National Corporate Governance Code. The 2016 Code is a standard for best practice and a support for communication among businesses from different countries. It guides Bulgarian companies on how to apply established best practices and principles of corporate governance.', 'This is the 2016 version of the Bulgarian National Corporate Governance Code. The 2016 Code is a standard for best practice and a support for communication among businesses from different countries. It guides Bulgarian companies on how to apply established best practices and principles of corporate governance.', 'Bulgaria', 'climate', 'in_force', '2016-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_13', ARRAY['bulgaria', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0e177a28-6a49-549e-ad66-4b81a76db9d1', 'Bulgaria Accountancy Act', 'Accountancy Act', 'This Act shall regulate: the requirements for entities’ ongoing accounting and accounting systems, accounting documents and accounting information, asset and liability stocktaking, and safekeeping of accounting information; the applicable financial accounting basis; the content and the drawing up of entities’ and group of entities’ financial statements, management reports, and reports on payments to governments; the obligations related to the independent financial audit and publishing entities’ and group of entities’ financial statements, management reports, and reports on payments to governments; the obligations and responsibilities of entity’s chief executive officer.', 'This Act shall regulate: the requirements for entities’ ongoing accounting and accounting systems, accounting documents and accounting information, asset and liability stocktaking, and safekeeping of accounting information; the applicable financial accounting basis; the content and the drawing up of entities’ and group of entities’ financial statements, management reports, and reports on payments to governments; the obligations related to the independent financial audit and publishing entities’ and group of entities’ financial statements, management reports, and reports on payments to governments; the obligations and responsibilities of entity’s chief executive officer.', 'This Act shall regulate: the requirements for entities’ ongoing accounting and accounting systems, accounting documents and accounting information, asset and liability stocktaking, and safekeeping of accounting information; the applicable financial accounting basis; the content and the drawing up of entities’ and group of entities’ financial statements, management reports, and reports on payments to governments; the obligations related to the independent financial audit and publishing entities’ and group of entities’ financial statements, management reports, and reports on payments to governments; the obligations and responsibilities of entity’s chief executive officer.', 'Bulgaria', 'climate', 'in_force', '2015-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_6', ARRAY['mandatory', 'other sustainability policy', 'bulgaria', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('40c7c9bc-41f6-5349-ae09-be761d5417c7', 'Bulgaria Regulation of 06/ on the procedure and templates', 'Regulation No. 1 of 06/04/2014 on the procedure and templates for providing information on waste activities, as well as the procedure for keeping public records', 'The purpose of this ordinance to obtain complete and reliable information about the activities on the waste by determining the order for keeping records and for the order and the terms for providing information on the respective samples by the persons under art and to receive complete and reliable information about the products placed on the market, after the use of which widespread waste is formed, according to the ordinances according to art. 13, para. 1 ZUO.', 'The purpose of this ordinance to obtain complete and reliable information about the activities on the waste by determining the order for keeping records and for the order and the terms for providing information on the respective samples by the persons under art and to receive complete and reliable information about the products placed on the market, after the use of which widespread waste is formed, according to the ordinances according to art. 13, para. 1 ZUO.', 'The purpose of this ordinance to obtain complete and reliable information about the activities on the waste by determining the order for keeping records and for the order and the terms for providing information on the respective samples by the persons under art and to receive complete and reliable information about the products placed on the market, after the use of which widespread waste is formed, according to the ordinances according to art. 13, para. 1 ZUO.', 'Bulgaria', 'climate', 'in_force', '2014-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_10', ARRAY['other sustainability policy', 'bulgaria', 'regulations', 'sdg11', 'mandatory', 'sdg6', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ecd1d69-510a-549c-a9de-d3fea740210c', 'Bulgaria Climate Change Mitigations Act', 'Climate Change Mitigations Act', 'The Climate Change Mitigations Act was enacted in Bulgaria in 2014 to promote efforts to reduce greenhouse gas emissions and mitigate the effects of climate change. The law establishes targets for reducing Bulgaria''s greenhouse gas emissions and sets out a range of measures to promote energy efficiency and the use of renewable energy sources. The law requires companies to report their greenhouse gas emissions and encourages the development of market-based mechanisms for reducing emissions, such as emissions trading schemes. The law also promotes the use of public transportation and the development of cycling infrastructure as a means of reducing carbon emissions from transportation. The Climate Change Mitigations Act is an important tool for promoting Bulgaria''s transition to a low-carbon economy and for supporting the country''s efforts to address the global challenge of climate change.', 'The Climate Change Mitigations Act was enacted in Bulgaria in 2014 to promote efforts to reduce greenhouse gas emissions and mitigate the effects of climate change. The law establishes targets for reducing Bulgaria''s greenhouse gas emissions and sets out a range of measures to promote energy efficiency and the use of renewable energy sources. The law requires companies to report their greenhouse gas emissions and encourages the development of market-based mechanisms for reducing emissions, such as emissions trading schemes. The law also promotes the use of public transportation and the development of cycling infrastructure as a means of reducing carbon emissions from transportation. The Climate Change Mitigations Act is an important tool for promoting Bulgaria''s transition to a low-carbon economy and for supporting the country''s efforts to address the global challenge of climate change.', 'The Climate Change Mitigations Act was enacted in Bulgaria in 2014 to promote efforts to reduce greenhouse gas emissions and mitigate the effects of climate change. The law establishes targets for reducing Bulgaria''s greenhouse gas emissions and sets out a range of measures to promote energy efficiency and the use of renewable energy sources. The law requires companies to report their greenhouse gas emissions and encourages the development of market-based mechanisms for reducing emissions, such as emissions trading schemes. The law also promotes the use of public transportation and the development of cycling infrastructure as a means of reducing carbon emissions from transportation. The Climate Change Mitigations Act is an important tool for promoting Bulgaria''s transition to a low-carbon economy and for supporting the country''s efforts to address the global challenge of climate change.', 'Bulgaria', 'climate', 'in_force', '2014-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_3', ARRAY['sdg8', 'sdg13', 'other sustainability policy', 'bulgaria', 'sdg2', 'regulations', 'sdg7', 'mandatory', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('31911876-e056-5849-a9c4-81cdcb30345e', 'Bulgaria Regulation of 23.07.2014 on waste classification', 'Regulation No. 2 of 23.07.2014 on waste classification', 'The purpose of the ordinance is the classification of waste, ensuring its environmentally sound management in accordance with the Waste Management Act (WMA) and the bylaws on its implementation.', 'The purpose of the ordinance is the classification of waste, ensuring its environmentally sound management in accordance with the Waste Management Act (WMA) and the bylaws on its implementation.', 'The purpose of the ordinance is the classification of waste, ensuring its environmentally sound management in accordance with the Waste Management Act (WMA) and the bylaws on its implementation.', 'Bulgaria', 'circularity', 'in_force', '2014-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_9', ARRAY['other sustainability policy', 'bulgaria', 'regulations', 'mandatory', 'sdg6', 'sdg12', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffc78d01-aab3-542d-85d1-2ab1ed68413c', 'Bulgarian Code For Corporate Governance', 'Bulgarian Code For Corporate Governance - 2007', 'The Bulgarian Code for Corporate Governance was first established in 2002 and updated in 2007. The code aims to promote good corporate governance practices among Bulgarian companies by providing a set of principles and guidelines for boards of directors, shareholders, and other stakeholders. The code covers various aspects of corporate governance, including the roles and responsibilities of board members, the protection of shareholder rights, the disclosure of financial information, and the management of conflicts of interest. The code also emphasizes the importance of ethical behavior and transparency in corporate decision-making. The updated 2007 version of the code introduced several changes, such as the strengthening of the rules on the independence of board members and the establishment of new standards for the composition and functioning of audit committees.', 'The Bulgarian Code for Corporate Governance was first established in 2002 and updated in 2007. The code aims to promote good corporate governance practices among Bulgarian companies by providing a set of principles and guidelines for boards of directors, shareholders, and other stakeholders. The code covers various aspects of corporate governance, including the roles and responsibilities of board members, the protection of shareholder rights, the disclosure of financial information, and the management of conflicts of interest. The code also emphasizes the importance of ethical behavior and transparency in corporate decision-making. The updated 2007 version of the code introduced several changes, such as the strengthening of the rules on the independence of board members and the establishment of new standards for the composition and functioning of audit committees.', 'The Bulgarian Code for Corporate Governance was first established in 2002 and updated in 2007. The code aims to promote good corporate governance practices among Bulgarian companies by providing a set of principles and guidelines for boards of directors, shareholders, and other stakeholders. The code covers various aspects of corporate governance, including the roles and responsibilities of board members, the protection of shareholder rights, the disclosure of financial information, and the management of conflicts of interest. The code also emphasizes the importance of ethical behavior and transparency in corporate decision-making. The updated 2007 version of the code introduced several changes, such as the strengthening of the rules on the independence of board members and the establishment of new standards for the composition and functioning of audit committees.', 'Bulgaria', 'climate', 'in_force', '2007-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_1', ARRAY['bulgaria', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9b3d99ae-02d6-5319-be35-f0448bd81dea', 'Bulgaria Environmental Protection Act', 'Environmental Protection Act', 'This Act provides for the conservation and use of environmental media, the control over the sources of pollution and damage, the establishment of permissible emission levels and of environmental quality standards, the management of the environmental media and of environmental factors, environmental impact assessment (EIA), the issuance of integrated permits for pollution prevention, reduction and control, the designation and management of areas placed under a special regime of protection, etc.', 'This Act provides for the conservation and use of environmental media, the control over the sources of pollution and damage, the establishment of permissible emission levels and of environmental quality standards, the management of the environmental media and of environmental factors, environmental impact assessment (EIA), the issuance of integrated permits for pollution prevention, reduction and control, the designation and management of areas placed under a special regime of protection, etc.', 'This Act provides for the conservation and use of environmental media, the control over the sources of pollution and damage, the establishment of permissible emission levels and of environmental quality standards, the management of the environmental media and of environmental factors, environmental impact assessment (EIA), the issuance of integrated permits for pollution prevention, reduction and control, the designation and management of areas placed under a special regime of protection, etc.', 'Bulgaria', 'climate', 'in_force', '2002-01-01'::date, 'Bulgaria', 'https://www.carrotsandsticks.org/policies/23_4', ARRAY['sdg4', 'sdg2', 'other sustainability policy', 'bulgaria', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7ab5757f-fbe6-5d1f-8add-ea8983419d25', 'Law on Investment in Cambodia', 'The Law on Investment in Cambodia', 'The Law on Investment of the Kingdom of Cambodia provides a legal framework to attract both domestic and foreign investments to foster economic development in the country. Its main goals include enhancing Cambodia''s competitiveness, modernizing local industries, and increasing productivity while supporting the country''s integration into regional and global supply chains. The law emphasizes creating an open, transparent, and predictable investment environment by offering incentives for investors and protecting their rights. The law applies to various investment types, including Qualified Investment Projects (QIPs), Expanded Qualified Investment Projects (EQIPs), and Guaranteed Investment Projects (GIPs), with specific tax incentives, customs duties exemptions, and protections for investors. It also ensures that investors have the right to repatriate profits and invest in Cambodia under a stable and favorable legal structure. The law outlines detailed provisions for the registration, operation, and potential nullification of investment projects and sets up a comprehensive dispute resolution mechanism.', 'The Law on Investment of the Kingdom of Cambodia provides a legal framework to attract both domestic and foreign investments to foster economic development in the country. Its main goals include enhancing Cambodia''s competitiveness, modernizing local industries, and increasing productivity while supporting the country''s integration into regional and global supply chains. The law emphasizes creating an open, transparent, and predictable investment environment by offering incentives for investors and protecting their rights. The law applies to various investment types, including Qualified Investment Projects (QIPs), Expanded Qualified Investment Projects (EQIPs), and Guaranteed Investment Projects (GIPs), with specific tax incentives, customs duties exemptions, and protections for investors. It also ensures that investors have the right to repatriate profits and invest in Cambodia under a stable and favorable legal structure. The law outlines detailed provisions for the registration, operation, and potential nullification of investment projects and sets up a comprehensive dispute resolution mechanism.', 'The Law on Investment of the Kingdom of Cambodia provides a legal framework to attract both domestic and foreign investments to foster economic development in the country. Its main goals include enhancing Cambodia''s competitiveness, modernizing local industries, and increasing productivity while supporting the country''s integration into regional and global supply chains. The law emphasizes creating an open, transparent, and predictable investment environment by offering incentives for investors and protecting their rights. The law applies to various investment types, including Qualified Investment Projects (QIPs), Expanded Qualified Investment Projects (EQIPs), and Guaranteed Investment Projects (GIPs), with specific tax incentives, customs duties exemptions, and protections for investors. It also ensures that investors have the right to repatriate profits and invest in Cambodia under a stable and favorable legal structure. The law outlines detailed provisions for the registration, operation, and potential nullification of investment projects and sets up a comprehensive dispute resolution mechanism.', 'Cambodia', 'climate', 'in_force', '2021-01-01'::date, 'Cambodia', 'https://www.carrotsandsticks.org/policies/27_4', ARRAY['regulations', 'sdg7', 'mandatory', 'sdg12', 'disclosure', 'cambodia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e85d84c8-fe54-504d-88b7-a90259f07457', 'Cambodian Securities Exchange (CSE) Corporate Governance Guidelines', 'Cambodian Securities Exchange (CSE) Corporate Governance Guidelines', 'The Prakas on Corporate Governance for Listed Public Enterprises sets out the requirements for corporate governance practices for public enterprises listed in Cambodia. The document outlines the responsibilities of listed public enterprises in ensuring transparency, accountability, and the protection of shareholders and stakeholders. Key provisions include the structure and roles of the Board of Directors, the protection of minority shareholders'' rights, and guidelines on the composition of committees such as the audit and risk management committees. The Prakas emphasizes the importance of ensuring that directors and senior officers act in the best interest of shareholders and disclose material information in a timely and transparent manner. It also mandates the creation of a code of conduct for directors and senior officers and requires clear disclosures regarding their compensation. Additionally, it highlights the duties of the board in risk management, internal control, and auditing, and specifies penalties for non-compliance.', 'The Prakas on Corporate Governance for Listed Public Enterprises sets out the requirements for corporate governance practices for public enterprises listed in Cambodia. The document outlines the responsibilities of listed public enterprises in ensuring transparency, accountability, and the protection of shareholders and stakeholders. Key provisions include the structure and roles of the Board of Directors, the protection of minority shareholders'' rights, and guidelines on the composition of committees such as the audit and risk management committees. The Prakas emphasizes the importance of ensuring that directors and senior officers act in the best interest of shareholders and disclose material information in a timely and transparent manner. It also mandates the creation of a code of conduct for directors and senior officers and requires clear disclosures regarding their compensation. Additionally, it highlights the duties of the board in risk management, internal control, and auditing, and specifies penalties for non-compliance.', 'The Prakas on Corporate Governance for Listed Public Enterprises sets out the requirements for corporate governance practices for public enterprises listed in Cambodia. The document outlines the responsibilities of listed public enterprises in ensuring transparency, accountability, and the protection of shareholders and stakeholders. Key provisions include the structure and roles of the Board of Directors, the protection of minority shareholders'' rights, and guidelines on the composition of committees such as the audit and risk management committees. The Prakas emphasizes the importance of ensuring that directors and senior officers act in the best interest of shareholders and disclose material information in a timely and transparent manner. It also mandates the creation of a code of conduct for directors and senior officers and requires clear disclosures regarding their compensation. Additionally, it highlights the duties of the board in risk management, internal control, and auditing, and specifies penalties for non-compliance.', 'Cambodia', 'climate', 'in_force', '2019-01-01'::date, 'Cambodia', 'https://www.carrotsandsticks.org/policies/27_1', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'cambodia', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('38798ab1-d6c0-5b77-bcac-9bf5c9644299', 'Cambodian Financial Industry Development Strategy', 'The Cambodian Financial Industry Development Strategy (2019-2023)', 'The National Financial Inclusion Strategy (NFIS) 2019–2025 aims to improve financial inclusion in Cambodia, supporting the country''s broader economic development goals. It addresses the barriers to financial access and aims to reduce poverty by enhancing access to financial services for underserved populations, including women and small and medium enterprises (SMEs). The strategy is aligned with the Financial Sector Development Strategy (FSDS) 2016–2025, focusing on providing affordable, accessible, and appropriate financial services to the Cambodian population, especially targeting rural areas and low-income households. Key objectives include increasing the use of formal financial services, promoting savings, improving financial literacy, and expanding access to credit, insurance, and digital payment systems. The strategy outlines priority activities for government agencies, financial institutions, and development partners, including infrastructure development, capacity building, and consumer protection. A specific goal is to reduce the financial exclusion of women from 27% to 13% and increase overall financial inclusion to 70% by 2025. The implementation of this strategy is expected to enhance Cambodia''s financial sector transparency, improve consumer empowerment, and boost the country''s economic growth.', 'The National Financial Inclusion Strategy (NFIS) 2019–2025 aims to improve financial inclusion in Cambodia, supporting the country''s broader economic development goals. It addresses the barriers to financial access and aims to reduce poverty by enhancing access to financial services for underserved populations, including women and small and medium enterprises (SMEs). The strategy is aligned with the Financial Sector Development Strategy (FSDS) 2016–2025, focusing on providing affordable, accessible, and appropriate financial services to the Cambodian population, especially targeting rural areas and low-income households. Key objectives include increasing the use of formal financial services, promoting savings, improving financial literacy, and expanding access to credit, insurance, and digital payment systems. The strategy outlines priority activities for government agencies, financial institutions, and development partners, including infrastructure development, capacity building, and consumer protection. A specific goal is to reduce the financial exclusion of women from 27% to 13% and increase overall financial inclusion to 70% by 2025. The implementation of this strategy is expected to enhance Cambodia''s financial sector transparency, improve consumer empowerment, and boost the country''s economic growth.', 'The National Financial Inclusion Strategy (NFIS) 2019–2025 aims to improve financial inclusion in Cambodia, supporting the country''s broader economic development goals. It addresses the barriers to financial access and aims to reduce poverty by enhancing access to financial services for underserved populations, including women and small and medium enterprises (SMEs). The strategy is aligned with the Financial Sector Development Strategy (FSDS) 2016–2025, focusing on providing affordable, accessible, and appropriate financial services to the Cambodian population, especially targeting rural areas and low-income households. Key objectives include increasing the use of formal financial services, promoting savings, improving financial literacy, and expanding access to credit, insurance, and digital payment systems. The strategy outlines priority activities for government agencies, financial institutions, and development partners, including infrastructure development, capacity building, and consumer protection. A specific goal is to reduce the financial exclusion of women from 27% to 13% and increase overall financial inclusion to 70% by 2025. The implementation of this strategy is expected to enhance Cambodia''s financial sector transparency, improve consumer empowerment, and boost the country''s economic growth.', 'Cambodia', 'climate', 'in_force', '2019-01-01'::date, 'Cambodia', 'https://www.carrotsandsticks.org/policies/27_2', ARRAY['sdg4', 'sdg10', 'cambodia', 'mandatory', 'sdg5', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg1', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9693b3eb-7a07-5c0b-8fb1-62ebcc9e4e4d', 'Cambodia Sub-Decree on Environmental Impact Assessment Process. No: 72', 'Sub-Decree on Environmental Impact Assessment Process. No: 72 ANRK.BK Phnom Penh, August 11, 1999', 'The main objectives of the decree are to: (1) determine an Environmental Impact Assessment (EIA) upon every private and public project or activity, and it must be reviewed by the Ministry of Environment (MoE), prior to the submission for a decision from the Royal Government. (2) To determine the type and size of the proposed project(s) and activities, including existing and ongoing activities in both private and public prior to undertaking the process of EIA. (3) Encourage public participation in the implementation of EIA process and take into account of their conceptual input and suggestion for re-consideration prior to the implementation of any project.', 'The main objectives of the decree are to: (1) determine an Environmental Impact Assessment (EIA) upon every private and public project or activity, and it must be reviewed by the Ministry of Environment (MoE), prior to the submission for a decision from the Royal Government. (2) To determine the type and size of the proposed project(s) and activities, including existing and ongoing activities in both private and public prior to undertaking the process of EIA. (3) Encourage public participation in the implementation of EIA process and take into account of their conceptual input and suggestion for re-consideration prior to the implementation of any project.', 'The main objectives of the decree are to: (1) determine an Environmental Impact Assessment (EIA) upon every private and public project or activity, and it must be reviewed by the Ministry of Environment (MoE), prior to the submission for a decision from the Royal Government. (2) To determine the type and size of the proposed project(s) and activities, including existing and ongoing activities in both private and public prior to undertaking the process of EIA. (3) Encourage public participation in the implementation of EIA process and take into account of their conceptual input and suggestion for re-consideration prior to the implementation of any project.', 'Cambodia', 'climate', 'in_force', '1999-01-01'::date, 'Cambodia', 'https://www.carrotsandsticks.org/policies/27_3', ARRAY['cambodia', 'regulations', 'sdg7', 'mandatory', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('39bce8cf-8ffe-5433-8352-3c5cf5803e35', 'Cameroon Law of December 14, 2016 establishing the mining', 'Law No. 2016/017 of December 14, 2016 establishing the mining code of Cameroon', 'This law establishing the Cameroon Mining Code, which includes 242 articles grouped into twelve (12) titles, aims to encourage, encourage and promote investments in the mining sector likely to contribute to the economic and social development of the country. To this end, it governs the recognition, research, exploitation, possession, transport, processing and marketing of mineral substances. It applies to mineral substances contained throughout the territory of the Republic of Cameroon, on the continental shelf, in territorial waters and in the exclusive economic zone, property of the State which exercises sovereign rights there.', 'This law establishing the Cameroon Mining Code, which includes 242 articles grouped into twelve (12) titles, aims to encourage, encourage and promote investments in the mining sector likely to contribute to the economic and social development of the country. To this end, it governs the recognition, research, exploitation, possession, transport, processing and marketing of mineral substances. It applies to mineral substances contained throughout the territory of the Republic of Cameroon, on the continental shelf, in territorial waters and in the exclusive economic zone, property of the State which exercises sovereign rights there.', 'This law establishing the Cameroon Mining Code, which includes 242 articles grouped into twelve (12) titles, aims to encourage, encourage and promote investments in the mining sector likely to contribute to the economic and social development of the country. To this end, it governs the recognition, research, exploitation, possession, transport, processing and marketing of mineral substances. It applies to mineral substances contained throughout the territory of the Republic of Cameroon, on the continental shelf, in territorial waters and in the exclusive economic zone, property of the State which exercises sovereign rights there.', 'Cameroon', 'climate', 'in_force', '2016-01-01'::date, 'Cameroon', 'https://www.carrotsandsticks.org/policies/28_1', ARRAY['cameroon', 'sdg14', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg6']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('83f09e11-3218-51c9-9da3-5757902d9111', 'Cameroon’s Corporate Governance Code (CEMAC)', 'Cameroon’s Corporate Governance Code (CEMAC)', 'The Cameroon Code of Corporate Governance 2023 is designed to provide a set of principles, precepts, and practices to guide companies in Cameroon in implementing effective corporate governance. It covers various levels of businesses, from large publicly traded companies to small and medium-sized enterprises (SMEs). The Code encourages companies to adopt best practices in governance to ensure sustainability, equity, integrity, and transparency in their operations. It emphasizes the importance of leadership responsibilities, decision-making processes, and stakeholder engagement. The Code is structured around several key principles such as sustainability, inclusion, transparency, and accountability, which guide the actions of company directors, management, and all stakeholders involved.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c44984f4-0dd2-5c42-8d53-4cf5f2237159', 'Canada Business Corporations Act (CBCA) Amendments', 'Canada Business Corporations Act (CBCA) Amendments', 'The Canada Business Corporations Act (CBCA) provides a comprehensive legal framework for the incorporation, organization, and governance of Canadian business corporations. It outlines the rights and obligations of shareholders, directors, and officers, ensuring corporate transparency, accountability, and adherence to fair business practices. Key provisions include the regulation of corporate finance, shareholder rights, governance standards, and reporting requirements. The Act emphasizes diversity in corporate leadership and mandates disclosures related to environmental, social, and governance (ESG) factors. Recent amendments focus on enhancing clarity in governance practices, safeguarding shareholder interests, and ensuring compliance with international best practices.', 'The Canada Business Corporations Act (CBCA) provides a comprehensive legal framework for the incorporation, organization, and governance of Canadian business corporations. It outlines the rights and obligations of shareholders, directors, and officers, ensuring corporate transparency, accountability, and adherence to fair business practices. Key provisions include the regulation of corporate finance, shareholder rights, governance standards, and reporting requirements. The Act emphasizes diversity in corporate leadership and mandates disclosures related to environmental, social, and governance (ESG) factors. Recent amendments focus on enhancing clarity in governance practices, safeguarding shareholder interests, and ensuring compliance with international best practices.', 'The Canada Business Corporations Act (CBCA) provides a comprehensive legal framework for the incorporation, organization, and governance of Canadian business corporations. It outlines the rights and obligations of shareholders, directors, and officers, ensuring corporate transparency, accountability, and adherence to fair business practices. Key provisions include the regulation of corporate finance, shareholder rights, governance standards, and reporting requirements. The Act emphasizes diversity in corporate leadership and mandates disclosures related to environmental, social, and governance (ESG) factors. Recent amendments focus on enhancing clarity in governance practices, safeguarding shareholder interests, and ensuring compliance with international best practices.', 'Canada', 'climate', 'in_force', '2024-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_100', ARRAY['regulations', 'sdg7', 'mandatory', 'sdg16', 'canada', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3b495889-caa9-5617-a475-da01ec58ea8a', 'Canada S-211 An Act to enact the Fighting Against', 'S-211 An Act to enact the Fighting Against Forced Labour and Child Labour in Supply Chains Act and to amend the Customs Tariff', 'The S-211 Act in Canada enforces reporting measures on government institutions and private entities to combat forced labor and child labor in supply chains. It also amends the Customs Tariff to prevent importing goods made using forced or child labor, targeting entities involved in supply chains.', 'The S-211 Act in Canada enforces reporting measures on government institutions and private entities to combat forced labor and child labor in supply chains. It also amends the Customs Tariff to prevent importing goods made using forced or child labor, targeting entities involved in supply chains.', 'The S-211 Act in Canada enforces reporting measures on government institutions and private entities to combat forced labor and child labor in supply chains. It also amends the Customs Tariff to prevent importing goods made using forced or child labor, targeting entities involved in supply chains.', 'Canada', 'climate', 'in_force', '2023-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_86', ARRAY['sdg8', 'regulations', 'mandatory', 'canada', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d03337d1-31b4-5e4f-a6ed-6ac4969f3177', 'Canada Corporate Responsibility to Protect Human Rights Act (Bill', 'Corporate Responsibility to Protect Human Rights Act (Bill C-262, Canada)', 'The Corporate Responsibility to Protect Human Rights Act, also known as Bill C-262, mandates Canadian businesses to prevent, address, and remedy adverse human rights impacts arising from their international activities. It establishes a due diligence framework obligating businesses to identify, mitigate, and report human rights risks across supply chains, affiliates, and business relationships. The Act includes provisions for annual reporting, private rights of action for victims, and the appointment of a commissioner to oversee compliance. It aligns with international human rights standards, such as the United Nations Guiding Principles on Business and Human Rights, and explicitly incorporates environmental considerations as integral to human rights.', 'The Corporate Responsibility to Protect Human Rights Act, also known as Bill C-262, mandates Canadian businesses to prevent, address, and remedy adverse human rights impacts arising from their international activities. It establishes a due diligence framework obligating businesses to identify, mitigate, and report human rights risks across supply chains, affiliates, and business relationships. The Act includes provisions for annual reporting, private rights of action for victims, and the appointment of a commissioner to oversee compliance. It aligns with international human rights standards, such as the United Nations Guiding Principles on Business and Human Rights, and explicitly incorporates environmental considerations as integral to human rights.', 'The Corporate Responsibility to Protect Human Rights Act, also known as Bill C-262, mandates Canadian businesses to prevent, address, and remedy adverse human rights impacts arising from their international activities. It establishes a due diligence framework obligating businesses to identify, mitigate, and report human rights risks across supply chains, affiliates, and business relationships. The Act includes provisions for annual reporting, private rights of action for victims, and the appointment of a commissioner to oversee compliance. It aligns with international human rights standards, such as the United Nations Guiding Principles on Business and Human Rights, and explicitly incorporates environmental considerations as integral to human rights.', 'Canada', 'climate', 'in_force', '2022-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_77', ARRAY['regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f86f3a1d-7327-580b-8c44-879a024e1fab', 'Canada Taxonomy Roadmap Report. Mobilizing Finance for Sustainable Growth', 'Taxonomy Roadmap Report. Mobilizing Finance for Sustainable Growth by Defining Green and Transition Investments', 'The Taxonomy Roadmap Report, developed by Canada’s Sustainable Finance Action Council (SFAC) in collaboration with the Taxonomy Technical Experts Group (TTEG), provides a comprehensive framework for a green and transition finance taxonomy in Canada. The initiative addresses the $115 billion annual climate investment gap needed for Canada’s net-zero transition by 2050. The taxonomy aims to standardize benchmarks for green and transition economic activities, mitigate greenwashing risks, and align capital flows with science-based climate pathways. Recommendations include robust governance led by federal and financial sector leadership, detailed framework architecture, and phased implementation (short-form taxonomy by mid-2023 and full taxonomy by 2025). Emphasis is placed on Indigenous and provincial participation, dynamic criteria updates, and interoperability with global taxonomies.', 'The Taxonomy Roadmap Report, developed by Canada’s Sustainable Finance Action Council (SFAC) in collaboration with the Taxonomy Technical Experts Group (TTEG), provides a comprehensive framework for a green and transition finance taxonomy in Canada. The initiative addresses the $115 billion annual climate investment gap needed for Canada’s net-zero transition by 2050. The taxonomy aims to standardize benchmarks for green and transition economic activities, mitigate greenwashing risks, and align capital flows with science-based climate pathways. Recommendations include robust governance led by federal and financial sector leadership, detailed framework architecture, and phased implementation (short-form taxonomy by mid-2023 and full taxonomy by 2025). Emphasis is placed on Indigenous and provincial participation, dynamic criteria updates, and interoperability with global taxonomies.', 'The Taxonomy Roadmap Report, developed by Canada’s Sustainable Finance Action Council (SFAC) in collaboration with the Taxonomy Technical Experts Group (TTEG), provides a comprehensive framework for a green and transition finance taxonomy in Canada. The initiative addresses the $115 billion annual climate investment gap needed for Canada’s net-zero transition by 2050. The taxonomy aims to standardize benchmarks for green and transition economic activities, mitigate greenwashing risks, and align capital flows with science-based climate pathways. Recommendations include robust governance led by federal and financial sector leadership, detailed framework architecture, and phased implementation (short-form taxonomy by mid-2023 and full taxonomy by 2025). Emphasis is placed on Indigenous and provincial participation, dynamic criteria updates, and interoperability with global taxonomies.', 'Canada', 'climate', 'in_force', '2022-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_83', ARRAY['sdg13', 'sdg7', 'sdg17', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('33f3187a-b642-52ad-af4c-c4a421120d44', 'Canada Act Respecting Transparency Measures in the Mining, Oil', 'Act Respecting Transparency Measures in the Mining, Oil, and Gas Industries (M-11.5)', 'This policy mandates transparency in monetary and in-kind payments made by mining, oil, and gas companies to specified payees, aiming to detect and discourage corruption and foster social acceptance of natural resource projects. Enacted under Québec’s jurisdiction, it requires entities meeting certain criteria (e.g., size, activity in Québec) to submit annual statements detailing payments such as royalties, taxes, fees, and bonuses exceeding CAD 100,000. The Autorité des marchés financiers (Authority) oversees compliance and may impose administrative penalties or audits. The law also supports international cooperation by allowing equivalency for reports submitted under similar transparency laws elsewhere. Non-compliance results in significant fines and administrative penalties.', 'This policy mandates transparency in monetary and in-kind payments made by mining, oil, and gas companies to specified payees, aiming to detect and discourage corruption and foster social acceptance of natural resource projects. Enacted under Québec’s jurisdiction, it requires entities meeting certain criteria (e.g., size, activity in Québec) to submit annual statements detailing payments such as royalties, taxes, fees, and bonuses exceeding CAD 100,000. The Autorité des marchés financiers (Authority) oversees compliance and may impose administrative penalties or audits. The law also supports international cooperation by allowing equivalency for reports submitted under similar transparency laws elsewhere. Non-compliance results in significant fines and administrative penalties.', 'This policy mandates transparency in monetary and in-kind payments made by mining, oil, and gas companies to specified payees, aiming to detect and discourage corruption and foster social acceptance of natural resource projects. Enacted under Québec’s jurisdiction, it requires entities meeting certain criteria (e.g., size, activity in Québec) to submit annual statements detailing payments such as royalties, taxes, fees, and bonuses exceeding CAD 100,000. The Autorité des marchés financiers (Authority) oversees compliance and may impose administrative penalties or audits. The law also supports international cooperation by allowing equivalency for reports submitted under similar transparency laws elsewhere. Non-compliance results in significant fines and administrative penalties.', 'Canada', 'climate', 'in_force', '2022-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_84', ARRAY['sdg8', 'regulations', 'sdg17', 'mandatory', 'sdg16', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00ef1b90-529e-5bed-b6b0-e62950fba79b', 'Capital Markets Modernization Taskforce Final Report (Ontario, Canada)', 'Capital Markets Modernization Taskforce Final Report (Ontario, Canada)', 'The Capital Markets Modernization Taskforce Final Report outlines a comprehensive set of recommendations to reform and enhance Ontario’s capital markets framework. The report, released in January 2021, proposes over 70 key measures to foster innovation, reduce regulatory burdens, ensure investor protection, and modernize the enforcement and governance structures of Ontario’s capital markets. Notable recommendations include the introduction of a new Capital Markets Act, enhanced diversity and environmental, social, and governance (ESG) disclosures, the establishment of a single self-regulatory organization (SRO), and greater integration of digital and technological advancements. The report emphasizes strengthening investor confidence and increasing Ontario’s competitiveness as a global capital market hub.', 'The Capital Markets Modernization Taskforce Final Report outlines a comprehensive set of recommendations to reform and enhance Ontario’s capital markets framework. The report, released in January 2021, proposes over 70 key measures to foster innovation, reduce regulatory burdens, ensure investor protection, and modernize the enforcement and governance structures of Ontario’s capital markets. Notable recommendations include the introduction of a new Capital Markets Act, enhanced diversity and environmental, social, and governance (ESG) disclosures, the establishment of a single self-regulatory organization (SRO), and greater integration of digital and technological advancements. The report emphasizes strengthening investor confidence and increasing Ontario’s competitiveness as a global capital market hub.', 'The Capital Markets Modernization Taskforce Final Report outlines a comprehensive set of recommendations to reform and enhance Ontario’s capital markets framework. The report, released in January 2021, proposes over 70 key measures to foster innovation, reduce regulatory burdens, ensure investor protection, and modernize the enforcement and governance structures of Ontario’s capital markets. Notable recommendations include the introduction of a new Capital Markets Act, enhanced diversity and environmental, social, and governance (ESG) disclosures, the establishment of a single self-regulatory organization (SRO), and greater integration of digital and technological advancements. The report emphasizes strengthening investor confidence and increasing Ontario’s competitiveness as a global capital market hub.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_39', ARRAY['sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'canada', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1365f8d5-f945-57d7-bca0-b209d5eb1d8a', 'Canada TSX and TSXV Listings Guide', 'TSX and TSXV Listings Guide', 'The TSX and TSXV Listings Guide 2021 provides a comprehensive roadmap for companies considering going public on the Toronto Stock Exchange (TSX) or TSX Venture Exchange (TSXV). It outlines the processes, benefits, and requirements for listing, emphasizing accessibility to North American capital markets. The guide highlights financing opportunities at various growth stages, global visibility for listed companies, and tailored listing criteria to accommodate industries like energy, mining, technology, and life sciences. It promotes TSX’s robust governance, liquidity, and investor reach, and includes information on innovative listing vehicles such as Special Purpose Acquisition Corporations (SPACs) and Capital Pool Companies (CPCs). Additionally, the guide underscores the importance of governance controls, financial reporting, and expert advisory in successful public offerings.', 'The TSX and TSXV Listings Guide 2021 provides a comprehensive roadmap for companies considering going public on the Toronto Stock Exchange (TSX) or TSX Venture Exchange (TSXV). It outlines the processes, benefits, and requirements for listing, emphasizing accessibility to North American capital markets. The guide highlights financing opportunities at various growth stages, global visibility for listed companies, and tailored listing criteria to accommodate industries like energy, mining, technology, and life sciences. It promotes TSX’s robust governance, liquidity, and investor reach, and includes information on innovative listing vehicles such as Special Purpose Acquisition Corporations (SPACs) and Capital Pool Companies (CPCs). Additionally, the guide underscores the importance of governance controls, financial reporting, and expert advisory in successful public offerings.', 'The TSX and TSXV Listings Guide 2021 provides a comprehensive roadmap for companies considering going public on the Toronto Stock Exchange (TSX) or TSX Venture Exchange (TSXV). It outlines the processes, benefits, and requirements for listing, emphasizing accessibility to North American capital markets. The guide highlights financing opportunities at various growth stages, global visibility for listed companies, and tailored listing criteria to accommodate industries like energy, mining, technology, and life sciences. It promotes TSX’s robust governance, liquidity, and investor reach, and includes information on innovative listing vehicles such as Special Purpose Acquisition Corporations (SPACs) and Capital Pool Companies (CPCs). Additionally, the guide underscores the importance of governance controls, financial reporting, and expert advisory in successful public offerings.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_63', ARRAY['sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'canada', 'disclosure', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('35347d3f-7d7b-5fb8-868b-eb03d1455b6f', 'Canada Towards Sustainable Mining (TSM) Climate Change Protocol', 'Towards Sustainable Mining (TSM) Climate Change Protocol', 'The purpose of this TSM protocol is to facilitate continual performance improvements in the mining sector related to the management of climate-related risks and opportunities, including associated mitigation and adaptation strategies, target-setting and reporting.', 'The purpose of this TSM protocol is to facilitate continual performance improvements in the mining sector related to the management of climate-related risks and opportunities, including associated mitigation and adaptation strategies, target-setting and reporting.', 'The purpose of this TSM protocol is to facilitate continual performance improvements in the mining sector related to the management of climate-related risks and opportunities, including associated mitigation and adaptation strategies, target-setting and reporting.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_67', ARRAY['sdg13', 'sdg7', 'mandatory', 'mandatory_regulations', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('815af1a3-7fe2-585a-8b03-cf6368749f68', 'Canada Towards Sustainable Mining (TSM) Indigenous and Community Relationships', 'Towards Sustainable Mining (TSM) Indigenous and Community Relationships Protocol', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of Indigenous and community relationships performance against Towards Sustainable Mining (TSM) indicators. The assessment protocol sets out the general expectations for Indigenous and community relationships as part of the TSM initiative.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of Indigenous and community relationships performance against Towards Sustainable Mining (TSM) indicators. The assessment protocol sets out the general expectations for Indigenous and community relationships as part of the TSM initiative.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of Indigenous and community relationships performance against Towards Sustainable Mining (TSM) indicators. The assessment protocol sets out the general expectations for Indigenous and community relationships as part of the TSM initiative.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_68', ARRAY['guidance_frameworks', 'sdg11', 'mandatory', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a37831ae-de68-59e5-9eb0-679b920f4d60', 'Canada Towards Sustainable Mining (TSM) Safety and Health Protocol', 'Towards Sustainable Mining (TSM) Safety and Health Protocol', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of safety and health performance against TSM indicators. The assessment protocol sets out the general expectations for safety and health as part of the TSM initiative. This protocol supports implementation of the TSM Safety and Health Framework.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of safety and health performance against TSM indicators. The assessment protocol sets out the general expectations for safety and health as part of the TSM initiative. This protocol supports implementation of the TSM Safety and Health Framework.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of safety and health performance against TSM indicators. The assessment protocol sets out the general expectations for safety and health as part of the TSM initiative. This protocol supports implementation of the TSM Safety and Health Framework.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_71', ARRAY['mandatory', 'mandatory_regulations', 'canada', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0add5249-9936-5b40-b427-f325a8a5e9f4', 'Canada Memorandum D9-1-6 Goods Manufactured or Produced by Prison', 'Memorandum D9-1-6 Goods Manufactured or Produced by Prison or Forced Labour', 'Memorandum D9-1-6 outlines the procedures for the importation of goods manufactured or produced by prison or forced labor into Canada. The importation of such goods is prohibited under Canadian law, and the memorandum provides guidance on identifying and reporting such goods. It also outlines the responsibilities of importers and customs officials in enforcing the prohibition, as well as the potential consequences for non-compliance. Overall, the memorandum serves as a tool to prevent the importation of goods produced through exploitative labor practices.', 'Memorandum D9-1-6 outlines the procedures for the importation of goods manufactured or produced by prison or forced labor into Canada. The importation of such goods is prohibited under Canadian law, and the memorandum provides guidance on identifying and reporting such goods. It also outlines the responsibilities of importers and customs officials in enforcing the prohibition, as well as the potential consequences for non-compliance. Overall, the memorandum serves as a tool to prevent the importation of goods produced through exploitative labor practices.', 'Memorandum D9-1-6 outlines the procedures for the importation of goods manufactured or produced by prison or forced labor into Canada. The importation of such goods is prohibited under Canadian law, and the memorandum provides guidance on identifying and reporting such goods. It also outlines the responsibilities of importers and customs officials in enforcing the prohibition, as well as the potential consequences for non-compliance. Overall, the memorandum serves as a tool to prevent the importation of goods produced through exploitative labor practices.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_75', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'canada', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d3ed8020-a15d-58b9-b035-6628df1f502c', 'Canada Bill S-211, An Act to enact the Fighting', 'Bill S-211, An Act to enact the Fighting Against Forced Labour and Child Labour in Supply Chains and to amend Customs Tariff', 'This enactment enacts the Fighting Against Forced Labour and Child Labour in Supply Chains Act, which imposes an obligation on certain government institutions and private-sector entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used by them or in their supply chains. The Act provides for an inspection regime applicable to entities and gives the Minister the power to require an entity to provide certain information. This enactment also amends the Customs Tariff to allow for a prohibition on the importation of goods manufactured or produced, in whole or in part, by forced labour or child labour as those terms are defined in the Fighting Against Forced Labour and Child Labour in Supply Chains Act.', 'This enactment enacts the Fighting Against Forced Labour and Child Labour in Supply Chains Act, which imposes an obligation on certain government institutions and private-sector entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used by them or in their supply chains. The Act provides for an inspection regime applicable to entities and gives the Minister the power to require an entity to provide certain information. This enactment also amends the Customs Tariff to allow for a prohibition on the importation of goods manufactured or produced, in whole or in part, by forced labour or child labour as those terms are defined in the Fighting Against Forced Labour and Child Labour in Supply Chains Act.', 'This enactment enacts the Fighting Against Forced Labour and Child Labour in Supply Chains Act, which imposes an obligation on certain government institutions and private-sector entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used by them or in their supply chains. The Act provides for an inspection regime applicable to entities and gives the Minister the power to require an entity to provide certain information. This enactment also amends the Customs Tariff to allow for a prohibition on the importation of goods manufactured or produced, in whole or in part, by forced labour or child labour as those terms are defined in the Fighting Against Forced Labour and Child Labour in Supply Chains Act.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_76', ARRAY['sdg8', 'regulations', 'mandatory', 'canada', 'disclosure', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2a710b5e-3864-52e0-b1c7-ccf12a92cddd', 'Responsible Business Conduct Abroad. Canada''s Strategy for the Future', 'Responsible Business Conduct Abroad. Canada''s Strategy for the Future (2022-2027)', 'Canada''s five-year strategy (2022-2027) aims to guide Canadian companies operating internationally to integrate responsible business conduct (RBC) as a core element of their success. The government, through the Trade Commissioner Service and its partners, will provide innovative tools like digital resources and a new standard, including a Digital RBC Attestation, to support companies of all sizes in adopting world-leading responsible practices.', 'Canada''s five-year strategy (2022-2027) aims to guide Canadian companies operating internationally to integrate responsible business conduct (RBC) as a core element of their success. The government, through the Trade Commissioner Service and its partners, will provide innovative tools like digital resources and a new standard, including a Digital RBC Attestation, to support companies of all sizes in adopting world-leading responsible practices.', 'Canada''s five-year strategy (2022-2027) aims to guide Canadian companies operating internationally to integrate responsible business conduct (RBC) as a core element of their success. The government, through the Trade Commissioner Service and its partners, will provide innovative tools like digital resources and a new standard, including a Digital RBC Attestation, to support companies of all sizes in adopting world-leading responsible practices.', 'Canada', 'climate', 'in_force', '2021-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_81', ARRAY['sdg13', 'sdg10', 'mandatory', 'sdg5', 'sdg16', 'mandatory_regulations', 'canada', 'disclosure', 'sdg1']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7f74db64-1ba0-5729-bcf8-a4f0fa782388', 'Canada Primer for Environmental & Social Disclosure', 'A Primer for Environmental & Social Disclosure 2020', 'This primer is an updated version of A Primer for Environmental & Social Disclosure, originally published by CPA Canada and TMX Group in 2014. It is intended for Toronto Stock Exchange (TSX)- and TSX Venture Exchange (TSXV)-listed issuers seeking to get started on the E&S aspects of their ESG disclosure, or looking to enhance their existing E&S disclosure in regulatory filings. It provides guidance with an emphasis on small- and medium-sized issuers.', 'This primer is an updated version of A Primer for Environmental & Social Disclosure, originally published by CPA Canada and TMX Group in 2014. It is intended for Toronto Stock Exchange (TSX)- and TSX Venture Exchange (TSXV)-listed issuers seeking to get started on the E&S aspects of their ESG disclosure, or looking to enhance their existing E&S disclosure in regulatory filings. It provides guidance with an emphasis on small- and medium-sized issuers.', 'This primer is an updated version of A Primer for Environmental & Social Disclosure, originally published by CPA Canada and TMX Group in 2014. It is intended for Toronto Stock Exchange (TSX)- and TSX Venture Exchange (TSXV)-listed issuers seeking to get started on the E&S aspects of their ESG disclosure, or looking to enhance their existing E&S disclosure in regulatory filings. It provides guidance with an emphasis on small- and medium-sized issuers.', 'Canada', 'climate', 'in_force', '2020-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_38', ARRAY['guidance_frameworks', 'sdg7', 'mandatory', 'canada', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0d27cf06-5faf-5aae-a649-b426ed81124a', 'Canada Technical Guide to Listing', 'Technical Guide to Listing 2020', 'This guide provides information about the process of listing on Toronto Stock Exchange (“TSX”) or TSX Venture Exchange (“TSXV”) (collectively “the Exchanges”) for both Canadian and international companies.', 'This guide provides information about the process of listing on Toronto Stock Exchange (“TSX”) or TSX Venture Exchange (“TSXV”) (collectively “the Exchanges”) for both Canadian and international companies.', 'This guide provides information about the process of listing on Toronto Stock Exchange (“TSX”) or TSX Venture Exchange (“TSXV”) (collectively “the Exchanges”) for both Canadian and international companies.', 'Canada', 'climate', 'in_force', '2020-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_40', ARRAY['sdg14', 'mandatory', 'mandatory_regulations', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2812594e-205f-58b0-bd58-625c5967466d', 'Canada Towards Sustainable Mining (TSM) Biodiversity conservation management control', 'Towards Sustainable Mining (TSM) Biodiversity conservation management control', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of biodiversity conservation management against TSM indicators. The assessment protocol sets out the general expectations for biodiversity conservation management as part of the TSM initiative. This protocol supports implementation of the TSM Mining and Biodiversity Conservation Framework.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of biodiversity conservation management against TSM indicators. The assessment protocol sets out the general expectations for biodiversity conservation management as part of the TSM initiative. This protocol supports implementation of the TSM Mining and Biodiversity Conservation Framework.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of biodiversity conservation management against TSM indicators. The assessment protocol sets out the general expectations for biodiversity conservation management as part of the TSM initiative. This protocol supports implementation of the TSM Mining and Biodiversity Conservation Framework.', 'Canada', 'climate', 'in_force', '2020-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_66', ARRAY['mandatory', 'mandatory_regulations', 'canada', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2757cd15-7682-541b-b772-2aa245f5c1b2', 'Canada Achieving a Sustainable Future. Federal Sustainable Development Strategy', 'Achieving a Sustainable Future. Federal Sustainable Development Strategy for Canada 2019 to 2022', 'The Federal Sustainable Development Strategy (FSDS) sets out the Government of Canada’s sustainable development priorities, establishes goals and targets, and identifies actions to achieve them. The 2019–2022 FSDS - Canada’s fourth - outlines what we will do to promote clean growth, ensure healthy ecosystems, and build safe, secure and sustainable communities over the next 3 years', 'The Federal Sustainable Development Strategy (FSDS) sets out the Government of Canada’s sustainable development priorities, establishes goals and targets, and identifies actions to achieve them. The 2019–2022 FSDS - Canada’s fourth - outlines what we will do to promote clean growth, ensure healthy ecosystems, and build safe, secure and sustainable communities over the next 3 years', 'The Federal Sustainable Development Strategy (FSDS) sets out the Government of Canada’s sustainable development priorities, establishes goals and targets, and identifies actions to achieve them. The 2019–2022 FSDS - Canada’s fourth - outlines what we will do to promote clean growth, ensure healthy ecosystems, and build safe, secure and sustainable communities over the next 3 years', 'Canada', 'climate', 'in_force', '2019-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_13', ARRAY['sdg13', 'sdg7', 'mandatory', 'mandatory_regulations', 'canada', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e6cdbe3d-b15a-5ead-8e3d-a802aa60b8a0', 'Canada Final Report of the Expert Panel on Sustainable', 'Final Report of the Expert Panel on Sustainable Finance. Mobilizing Finance for Sustainable Growth', 'This Final Report of the Expert Panel - Mobilizing Finance for Sustainable Growth - presents a package of recommendations aimed at aligning mainstream financial activities with the transition to a competitive low-emissions, climate-smart economy. The recommendations derive from extensive cross-country consultations and international discussions undertaken over the last year. Together, they reflect a widely held view that accelerating the transition to a sustainable economy in Canada will require a fundamental restructuring of multiple market, economic and institutional systems. Though the recommendations center on finance, in some cases it is necessary to address the underlying behaviours and practices for financing to be attracted to the right places, and achieve its targeted impact', 'This Final Report of the Expert Panel - Mobilizing Finance for Sustainable Growth - presents a package of recommendations aimed at aligning mainstream financial activities with the transition to a competitive low-emissions, climate-smart economy. The recommendations derive from extensive cross-country consultations and international discussions undertaken over the last year. Together, they reflect a widely held view that accelerating the transition to a sustainable economy in Canada will require a fundamental restructuring of multiple market, economic and institutional systems. Though the recommendations center on finance, in some cases it is necessary to address the underlying behaviours and practices for financing to be attracted to the right places, and achieve its targeted impact', 'This Final Report of the Expert Panel - Mobilizing Finance for Sustainable Growth - presents a package of recommendations aimed at aligning mainstream financial activities with the transition to a competitive low-emissions, climate-smart economy. The recommendations derive from extensive cross-country consultations and international discussions undertaken over the last year. Together, they reflect a widely held view that accelerating the transition to a sustainable economy in Canada will require a fundamental restructuring of multiple market, economic and institutional systems. Though the recommendations center on finance, in some cases it is necessary to address the underlying behaviours and practices for financing to be attracted to the right places, and achieve its targeted impact', 'Canada', 'climate', 'in_force', '2019-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_14', ARRAY['sdg13', 'mandatory', 'mandatory_regulations', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e663fb9-ae21-5d66-b698-46a0280a1666', 'Canada CSA Staff Notice 51- 358. Reporting on Climate', 'CSA Staff Notice 51- 358. Reporting on Climate Change-related Risks', 'The key objective of this notice is to provide issuers, particularly smaller issuers, with guidance as to how they might approach preparing disclosures of material climate change-related risks. In particular, the guidance contained in this notice is primarily focused on issuers'' disclosure obligations as they relate to the MD&A and AIF. In addition to addressing regulatory requirements, these disclosures provide issuers with an opportunity to inform investors about the sustainability of their business model and to provide insights into how they are mitigating and adapting to these risks.', 'The key objective of this notice is to provide issuers, particularly smaller issuers, with guidance as to how they might approach preparing disclosures of material climate change-related risks. In particular, the guidance contained in this notice is primarily focused on issuers'' disclosure obligations as they relate to the MD&A and AIF. In addition to addressing regulatory requirements, these disclosures provide issuers with an opportunity to inform investors about the sustainability of their business model and to provide insights into how they are mitigating and adapting to these risks.', 'The key objective of this notice is to provide issuers, particularly smaller issuers, with guidance as to how they might approach preparing disclosures of material climate change-related risks. In particular, the guidance contained in this notice is primarily focused on issuers'' disclosure obligations as they relate to the MD&A and AIF. In addition to addressing regulatory requirements, these disclosures provide issuers with an opportunity to inform investors about the sustainability of their business model and to provide insights into how they are mitigating and adapting to these risks.', 'Canada', 'climate', 'in_force', '2019-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_44', ARRAY['sdg13', 'sdg7', 'mandatory', 'mandatory_regulations', 'canada', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3486a7e7-ecfa-586f-8ba2-d5186f286253', 'Canada CSA Multilateral Staff Notice 58-311. Report on Fifth', 'CSA Multilateral Staff Notice 58-311. Report on Fifth Staff Review of Disclosure Regarding Women on Boards and in Executive Officer Positions', 'This report outlines key trends from a recent review of public disclosure regarding women on boards and in executive officer positions as required by Form 58-101F1 Corporate Governance Disclosure (the disclosure requirements) of National Instrument 58-101 Disclosure of Corporate Governance Practices (NI 58-101).', 'This report outlines key trends from a recent review of public disclosure regarding women on boards and in executive officer positions as required by Form 58-101F1 Corporate Governance Disclosure (the disclosure requirements) of National Instrument 58-101 Disclosure of Corporate Governance Practices (NI 58-101).', 'This report outlines key trends from a recent review of public disclosure regarding women on boards and in executive officer positions as required by Form 58-101F1 Corporate Governance Disclosure (the disclosure requirements) of National Instrument 58-101 Disclosure of Corporate Governance Practices (NI 58-101).', 'Canada', 'climate', 'in_force', '2019-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_59', ARRAY['mandatory', 'sdg5', 'sdg16', 'mandatory_regulations', 'canada', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d9055ff6-945b-5d7e-abf2-05af21a6e0b0', 'Canada Towards Sustainable Mining (TSM) Prevention of Child', 'Towards Sustainable Mining (TSM) Prevention of Child and Forced Labour Verification Protocol', 'The purpose of the verification protocol is to provide guidance to the member companies on verification requirements regarding the prevention of child labour and forced labour. The verification protocol sets out the general approach taken to verifying that processes are in place to ensure that neither child or forced labour as defined by ILO conventions are occurring at TSM participating facilities.', 'The purpose of the verification protocol is to provide guidance to the member companies on verification requirements regarding the prevention of child labour and forced labour. The verification protocol sets out the general approach taken to verifying that processes are in place to ensure that neither child or forced labour as defined by ILO conventions are occurring at TSM participating facilities.', 'The purpose of the verification protocol is to provide guidance to the member companies on verification requirements regarding the prevention of child labour and forced labour. The verification protocol sets out the general approach taken to verifying that processes are in place to ensure that neither child or forced labour as defined by ILO conventions are occurring at TSM participating facilities.', 'Canada', 'climate', 'in_force', '2019-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_70', ARRAY['guidance_frameworks', 'sdg8', 'mandatory', 'sdg12', 'disclosure', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bacaa2ba-c8de-5e41-a38f-c076685a8851', 'Canada Towards Sustainable Mining (TSM) Tailings Management Protocol', 'Towards Sustainable Mining (TSM) Tailings Management Protocol', 'The previous version of the Tailings Management Protocol (the Protocol), dated November 2017, included requirements for emergency preparedness as part of Indicator 5 and referred to Developing an Operation, Maintenance, and Surveillance Manual for Tailings and Water Management Facilities (the OMS Guide). Guidance on emergency preparedness has been moved to A Guide to the Management of Tailings Facilities (the Tailings Guide, Version 3.1, dated February 2019).', 'The previous version of the Tailings Management Protocol (the Protocol), dated November 2017, included requirements for emergency preparedness as part of Indicator 5 and referred to Developing an Operation, Maintenance, and Surveillance Manual for Tailings and Water Management Facilities (the OMS Guide). Guidance on emergency preparedness has been moved to A Guide to the Management of Tailings Facilities (the Tailings Guide, Version 3.1, dated February 2019).', 'The previous version of the Tailings Management Protocol (the Protocol), dated November 2017, included requirements for emergency preparedness as part of Indicator 5 and referred to Developing an Operation, Maintenance, and Surveillance Manual for Tailings and Water Management Facilities (the OMS Guide). Guidance on emergency preparedness has been moved to A Guide to the Management of Tailings Facilities (the Tailings Guide, Version 3.1, dated February 2019).', 'Canada', 'climate', 'in_force', '2019-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_73', ARRAY['guidance_frameworks', 'sdg7', 'sdg11', 'mandatory', 'sdg6', 'canada', 'disclosure', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('46be0f0d-7e8d-5ca1-8f0d-de958561dff4', 'Canada Impact Assessment Act ( SC 2019, c. 28', 'Impact Assessment Act ( SC 2019, c. 28, s. 1)', 'The Canadian Impact Assessment Act streamlines environmental reviews for projects, prioritizing sustainability and Indigenous rights. It mandates rigorous assessments for major projects like mines and pipelines, considering climate change and public input. Smaller projects typically require less intensive reviews or are exempt. This Act aims to balance development with environmental protection and community engagement.', 'The Canadian Impact Assessment Act streamlines environmental reviews for projects, prioritizing sustainability and Indigenous rights. It mandates rigorous assessments for major projects like mines and pipelines, considering climate change and public input. Smaller projects typically require less intensive reviews or are exempt. This Act aims to balance development with environmental protection and community engagement.', 'The Canadian Impact Assessment Act streamlines environmental reviews for projects, prioritizing sustainability and Indigenous rights. It mandates rigorous assessments for major projects like mines and pipelines, considering climate change and public input. Smaller projects typically require less intensive reviews or are exempt. This Act aims to balance development with environmental protection and community engagement.', 'Canada', 'climate', 'in_force', '2019-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_82', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg16', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f342837d-cf54-5919-8e64-5a67bfb842f9', 'Canada Bill C-423. An Act respecting the fight against', 'Bill C-423. An Act respecting the fight against certain forms of modern slavery through the imposition of certain measures and amending the Customs Tariff', 'This enactment enacts the Modern Slavery Act, which imposes an obligation on certain entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used at any step in the manufacture, production, growing, extraction or processing of goods in Canada or elsewhere by the entity or in the manufacture, production, growing, extraction or processing of goods imported into Canada by the entity. The Act provides for an inspection regime and gives the Minister the power to require an entity to provide certain information.', 'This enactment enacts the Modern Slavery Act, which imposes an obligation on certain entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used at any step in the manufacture, production, growing, extraction or processing of goods in Canada or elsewhere by the entity or in the manufacture, production, growing, extraction or processing of goods imported into Canada by the entity. The Act provides for an inspection regime and gives the Minister the power to require an entity to provide certain information.', 'This enactment enacts the Modern Slavery Act, which imposes an obligation on certain entities to report on the measures taken to prevent and reduce the risk that forced labour or child labour is used at any step in the manufacture, production, growing, extraction or processing of goods in Canada or elsewhere by the entity or in the manufacture, production, growing, extraction or processing of goods imported into Canada by the entity. The Act provides for an inspection regime and gives the Minister the power to require an entity to provide certain information.', 'Canada', 'climate', 'in_force', '2018-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_10', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg16', 'canada', 'disclosure', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb423e30-c994-54d3-a560-d8388d686810', 'Canada Corporate Governance Guideline', 'Corporate Governance Guideline 2018', 'This guideline communicates the Office of the Superintendent of Financial Institutions Canada ( OSFI’s) expectations with respect to corporate governance of federally regulated financial institutions (FRFIs). It applies to all FRFIs other than the branch operations of foreign banks and foreign insurance companies.', 'This guideline communicates the Office of the Superintendent of Financial Institutions Canada ( OSFI’s) expectations with respect to corporate governance of federally regulated financial institutions (FRFIs). It applies to all FRFIs other than the branch operations of foreign banks and foreign insurance companies.', 'This guideline communicates the Office of the Superintendent of Financial Institutions Canada ( OSFI’s) expectations with respect to corporate governance of federally regulated financial institutions (FRFIs). It applies to all FRFIs other than the branch operations of foreign banks and foreign insurance companies.', 'Canada', 'governance', 'in_force', '2018-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_20', ARRAY['guidance_frameworks', 'sdg16', 'canada', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3b788991-f929-5db3-9733-b5631265bb9b', 'Canada Chlor-Alkali Mercury Liquid Effluent Regulations', 'Chlor-Alkali Mercury Liquid Effluent Regulations', 'The 2018 Chlor-Alkali Mercury Liquid Effluent Regulations (CAMLER) in Canada are designed to reduce the amount of mercury that is released into the environment as a result of the chlor-alkali industry. The regulations place obligations on businesses that manufacture or import chlor-alkali products. Under CAMLER, businesses must limit the amount of mercury that is present in their effluent to a maximum concentration of 0.001 mg/L. They are required to monitor and report on their effluent levels, and to implement measures to ensure that their operations do not result in mercury releases that exceed regulatory limits. Businesses must also conduct environmental risk assessments to identify potential risks to the environment and human health, and to develop and implement risk management plans to mitigate these risks. They are required to notify the government of any significant environmental releases of mercury, and to implement measures to prevent future releases. In addition to these regulatory requirements, businesses are encouraged to adopt best practices for mercury management, such as implementing mercury-free technologies and processes, and recycling and reusing mercury where possible.', 'The 2018 Chlor-Alkali Mercury Liquid Effluent Regulations (CAMLER) in Canada are designed to reduce the amount of mercury that is released into the environment as a result of the chlor-alkali industry. The regulations place obligations on businesses that manufacture or import chlor-alkali products. Under CAMLER, businesses must limit the amount of mercury that is present in their effluent to a maximum concentration of 0.001 mg/L. They are required to monitor and report on their effluent levels, and to implement measures to ensure that their operations do not result in mercury releases that exceed regulatory limits. Businesses must also conduct environmental risk assessments to identify potential risks to the environment and human health, and to develop and implement risk management plans to mitigate these risks. They are required to notify the government of any significant environmental releases of mercury, and to implement measures to prevent future releases. In addition to these regulatory requirements, businesses are encouraged to adopt best practices for mercury management, such as implementing mercury-free technologies and processes, and recycling and reusing mercury where possible.', 'The 2018 Chlor-Alkali Mercury Liquid Effluent Regulations (CAMLER) in Canada are designed to reduce the amount of mercury that is released into the environment as a result of the chlor-alkali industry. The regulations place obligations on businesses that manufacture or import chlor-alkali products. Under CAMLER, businesses must limit the amount of mercury that is present in their effluent to a maximum concentration of 0.001 mg/L. They are required to monitor and report on their effluent levels, and to implement measures to ensure that their operations do not result in mercury releases that exceed regulatory limits. Businesses must also conduct environmental risk assessments to identify potential risks to the environment and human health, and to develop and implement risk management plans to mitigate these risks. They are required to notify the government of any significant environmental releases of mercury, and to implement measures to prevent future releases. In addition to these regulatory requirements, businesses are encouraged to adopt best practices for mercury management, such as implementing mercury-free technologies and processes, and recycling and reusing mercury where possible.', 'Canada', 'climate', 'in_force', '2018-01-01'::d