INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03ae7e04-8d9e-5cbf-a40a-77f899ca8828', 'Canada Towards Sustainable Mining (TSM) Crisis management and communications', 'Towards Sustainable Mining (TSM) Crisis management and communications planning protocol', 'The purpose of the assessment protocol is to provide guidance to the member companies in completing their evaluation of crisis management and communications planning against TSM indicators. The assessment protocol sets out the general expectations of MAC for crisis management and communications planning by its member companies in support of the TSM initiative.', 'The purpose of the assessment protocol is to provide guidance to the member companies in completing their evaluation of crisis management and communications planning against TSM indicators. The assessment protocol sets out the general expectations of MAC for crisis management and communications planning by its member companies in support of the TSM initiative.', 'The purpose of the assessment protocol is to provide guidance to the member companies in completing their evaluation of crisis management and communications planning against TSM indicators. The assessment protocol sets out the general expectations of MAC for crisis management and communications planning by its member companies in support of the TSM initiative.', 'Canada', 'climate', 'in_force', '2018-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_69', ARRAY['sdg13', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'canada']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('07ce186a-9c54-509b-9208-3ad7ca522862', 'Canada Towards Sustainable Mining (TSM) Water Stewardship Protocol', 'Towards Sustainable Mining (TSM) Water Stewardship Protocol', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of water stewardship performance against TSM indicators. The assessment protocol sets out the general expectations for water stewardship as part of the TSM initiative. This protocol supports implementation of the TSM Water Stewardship Framework.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of water stewardship performance against TSM indicators. The assessment protocol sets out the general expectations for water stewardship as part of the TSM initiative. This protocol supports implementation of the TSM Water Stewardship Framework.', 'The purpose of the assessment protocol is to provide guidance to facilities in completing their evaluation of water stewardship performance against TSM indicators. The assessment protocol sets out the general expectations for water stewardship as part of the TSM initiative. This protocol supports implementation of the TSM Water Stewardship Framework.', 'Canada', 'climate', 'in_force', '2018-01-01'::date, 'Canada', 'https://www.carrotsandsticks.org/policies/29_72', ARRAY['mandatory', 'sdg6', 'mandatory_regulations', 'canada', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
